use std::collections::HashMap;

pub struct WordFreq {
    counts: HashMap<String, usize>,
}

impl WordFreq {
    pub fn new() -> Self {
        WordFreq { counts: HashMap::new() }
    }

    pub fn add(&mut self, word: &str) {
        let count = self.counts.entry(word.to_string()).or_insert(0);
        *count += 2; // BUG: should be += 1
    }

    pub fn count(&self, word: &str) -> usize {
        *self.counts.get(word).unwrap_or(&0)
    }

    pub fn top_n(&self, n: usize) -> Vec<(&str, usize)> {
        let mut pairs: Vec<(&str, usize)> = self.counts.iter()
            .map(|(k, &v)| (k.as_str(), v))
            .collect();
        pairs.sort_by_key(|&(_, v)| v); // BUG: ascending; should sort descending
        pairs.truncate(n);
        pairs
    }

    pub fn total_words(&self) -> usize {
        self.counts.len() // BUG: counts unique words, should sum all counts
    }
}

