use word_freq::WordFreq;

#[test]
fn test_add_count() {
    let mut wf = WordFreq::new();
    wf.add("hello");
    wf.add("hello");
    wf.add("hello");
    assert_eq!(wf.count("hello"), 3);
    assert_eq!(wf.count("world"), 0);
}

#[test]
fn test_top_n() {
    let mut wf = WordFreq::new();
    for _ in 0..3 { wf.add("apple"); }
    for _ in 0..5 { wf.add("banana"); }
    for _ in 0..1 { wf.add("cherry"); }
    let top2 = wf.top_n(2);
    assert_eq!(top2.len(), 2);
    // highest-frequency words first
    assert_eq!(top2[0], ("banana", 5));
    assert_eq!(top2[1], ("apple", 3));
}

#[test]
fn test_total_words() {
    let mut wf = WordFreq::new();
    wf.add("a");
    wf.add("a");
    wf.add("b");
    wf.add("b");
    wf.add("b");
    assert_eq!(wf.total_words(), 5);
}
